@prefix mpr: <https://w3id.org/ogc/hosted/demo/marine-protections/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://w3id.org/ogc/hosted/demo/marine-protections/site/test> ;
            sh:resultMessage "mpr:bottomTrawling must be a single regulation status code." ;
            sh:resultPath mpr:bottomTrawling ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:InConstraintComponent ;
            sh:sourceShape [ sh:in ( 0 1 2 3 ) ;
                    sh:maxCount 1 ;
                    sh:message "mpr:bottomTrawling must be a single regulation status code." ;
                    sh:path mpr:bottomTrawling ] ;
            sh:value 7 ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://w3id.org/ogc/hosted/demo/marine-protections/site/test> ;
            sh:resultMessage "mpr:levelOfFishingProtection must be a single integer from 0 to 5." ;
            sh:resultPath mpr:levelOfFishingProtection ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:InConstraintComponent ;
            sh:sourceShape [ sh:in ( 0 1 2 3 4 5 ) ;
                    sh:maxCount 1 ;
                    sh:message "mpr:levelOfFishingProtection must be a single integer from 0 to 5." ;
                    sh:minCount 1 ;
                    sh:path mpr:levelOfFishingProtection ] ;
            sh:value 9 ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
